fn check(n: i32) -> Result<i32, String> {
    if n > 0 {
        Ok(n)
    } else {
        Err(String::from("neg"))
    }
}

fn main() {
    let r = check(-1);
    assert!(r.is_err());
    assert_eq!(check(2), Ok(2));
    println!("{:?}", r);
}
